"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/input.css";
import "./shared/input-2.css";
import "./shared/input-group.css";
import "./input.css";

const fieldText =
  "w-full min-w-0 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm";

export type InputProps = ComponentProps<"input"> & {
  /** Fixed text or an icon before the value, e.g. "caliper.app/". */
  leading?: ReactNode;
  /** Text, an icon or a status after the value, e.g. a spinner or a count. */
  trailing?: ReactNode;
};

/**
 * A recessed text field. Fields sit slightly below the paper (an inner shade
 * and a 3:1 ring); buttons stand on it, so what you fill and what you press
 * never look alike.
 */
export function Input({ className, leading, trailing, ...props }: InputProps) {
  if (leading === undefined && trailing === undefined) {
    return (
      <input
        data-slot="input"
        className={cn("flex h-[var(--control-height)] rounded-button px-3", fieldText, className)}
        {...props}
      />
    );
  }
  return (
    <span
      data-slot="input-group"
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || props["aria-invalid"] === "true" || undefined}
      data-readonly={props.readOnly || undefined}
      className={cn("flex h-[var(--control-height)] w-full min-w-0 items-center gap-2 rounded-button px-3", className)}
    >
      {leading !== undefined && <span data-slot="input-affix">{leading}</span>}
      <input data-slot="input-bare" className={cn("h-full flex-1 bg-transparent", fieldText)} {...props} />
      {trailing !== undefined && <span data-slot="input-trailing">{trailing}</span>}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import { useState, type ReactNode } from "react";
import { Search } from "./search";
import { cn } from "./lib/cn";
import "./not-found-page.css";

/** A dead end that helps: what happened in plain words, a way home, and a few places people usually wanted. */
export function NotFoundPage({
  code = "404",
  title = "We can't find that page",
  description = "The link may be old, or the page may have moved. Here are some places to start.",
  actions,
  suggestions,
  onSearch,
  className,
}: {
  code?: string;
  title?: string;
  description?: string;
  /** Usually a primary "Go home" button and a quiet "Go back". */
  actions?: ReactNode;
  suggestions?: readonly { label: string; href: string; description?: string }[];
  /** Adds a search field; called with the query. */
  onSearch?: (query: string) => void;
  className?: string;
}) {
  const [query, setQuery] = useState("");
  return (
    <main data-slot="not-found" className={cn("mx-auto grid w-full max-w-xl justify-items-center gap-6 px-4 py-16 text-center", className)}>
      <p aria-hidden="true" data-slot="error-code">
        {code}
      </p>
      <div className="grid gap-2">
        <h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">{title}</h1>
        <p className="text-sm text-muted-foreground">
          <span className="sr-only">Error {code}. </span>
          {description}
        </p>
      </div>
      {onSearch && (
        <form
          role="search"
          className="w-full max-w-sm"
          onSubmit={(event) => {
            event.preventDefault();
            if (query.trim()) onSearch(query.trim());
          }}
        >
          <Search aria-label="Search the site" placeholder="Search the site" value={query} onChange={(e) => setQuery(e.target.value)} onClear={() => setQuery("")} />
        </form>
      )}
      {actions && <div className="flex flex-wrap items-center justify-center gap-3">{actions}</div>}
      {suggestions && suggestions.length > 0 && (
        <nav aria-label="Suggested pages" className="w-full text-left">
          <ul className="divide-y divide-border rounded-overlay border border-border">
            {suggestions.map((s) => (
              <li key={s.href + s.label}>
                <a href={s.href} data-slot="suggestion">
                  <span className="text-sm font-medium">{s.label}</span>
                  {s.description && <span className="text-xs text-muted-foreground">{s.description}</span>}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      )}
    </main>
  );
}

"use client";

import { Search as SearchIcon, X } from "lucide-react";
import {
  useImperativeHandle,
  useRef,
  type ChangeEventHandler,
  type ComponentProps,
} from "react";
import { Button } from "./button";
import { Input } from "./input";
import { cn } from "./lib/cn";

export type SearchProps = Omit<
  ComponentProps<"input">,
  "type" | "value" | "defaultValue" | "onChange"
> & {
  value: string;
  onChange: ChangeEventHandler<HTMLInputElement>;
  onClear: () => void;
  clearLabel?: string;
};

export function Search({
  value,
  onChange,
  onClear,
  clearLabel = "Clear search",
  ref,
  className,
  disabled,
  readOnly,
  ...props
}: SearchProps) {
  const input = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => input.current!, []);
  return (
    <div data-slot="search" className="relative w-full min-w-0">
      <SearchIcon
        aria-hidden="true"
        className="pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"
      />
      <Input
        {...props}
        ref={input}
        type="search"
        value={value}
        onChange={onChange}
        disabled={disabled}
        readOnly={readOnly}
        className={cn(
          "appearance-none ps-9 pe-[calc(var(--control-height)+8px)] [&::-webkit-search-cancel-button]:appearance-none",
          className,
        )}
      />
      {value.length > 0 && !disabled && !readOnly && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={clearLabel}
          className="absolute end-0 top-0"
          onClick={() => {
            onClear();
            input.current?.focus();
          }}
        >
          <X aria-hidden="true" />
        </Button>
      )}
    </div>
  );
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* Shared by combobox.tsx, input.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="input"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Recessed to fill. One ring for every field: 3:1 at rest, darker on
     hover, a 2px ember ring with a soft halo on focus, danger when invalid.
     Disabled and read-only drop into the sunken fill and stay legible. */
  [data-slot="input"] {
    border: 0;
    background-color: var(--field);
    box-shadow: var(--shadow-field);
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="input"] {
      transition: none;
    }
  }
}

/* Shared by combobox.tsx, input.tsx, select-menu.tsx, select.tsx, textarea.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  @media (hover: hover) {
    :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):hover:enabled:not(:focus-visible):not([aria-invalid="true"]) {
      box-shadow: var(--shadow-field-hover);
    }
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):focus-visible {
    outline: none;
    box-shadow: var(--shadow-field-focus);
    transition: none;
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"])[aria-invalid="true"] {
    box-shadow: var(--shadow-field-invalid);
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"])[aria-invalid="true"]:focus-visible {
    box-shadow:
      var(--shadow-field-invalid),
      0 0 0 4px color-mix(in srgb, var(--danger) 18%, transparent);
  }
  :is([data-slot="input"], [data-slot="textarea"], [data-slot="select"]):disabled {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  :is([data-slot="input"], [data-slot="textarea"])[readonly] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
  }
}

/* Shared by input.tsx, money-field.tsx, phone-field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  @media (hover: hover) {
    :is([data-slot="input-group"], [data-slot="money-field"], [data-slot="phone-field-control"]):not([data-disabled]):not([data-invalid]):hover:not(:focus-within) {
      box-shadow: var(--shadow-field-hover);
    }
  }
  :is([data-slot="input-group"], [data-slot="money-field"], [data-slot="phone-field-control"]):focus-within {
    outline: none;
    box-shadow: var(--shadow-field-focus);
    transition: none;
  }
}

/* input.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Recessed to fill. One ring for every field: 3:1 at rest, darker on
     hover, a 2px ember ring with a soft halo on focus, danger when invalid.
     Disabled and read-only drop into the sunken fill and stay legible. */
  [data-slot="input-group"] {
    border: 0;
    background-color: var(--field);
    box-shadow: var(--shadow-field);
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }
  [data-slot="input-group"][data-invalid] {
    box-shadow: var(--shadow-field-invalid);
  }
  [data-slot="input-group"][data-invalid]:focus-within {
    box-shadow:
      var(--shadow-field-invalid),
      0 0 0 4px color-mix(in srgb, var(--danger) 18%, transparent);
  }
  [data-slot="input-group"][data-disabled] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  [data-slot="input-group"][data-readonly] {
    background-color: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
  }
  [data-slot="input-bare"] {
    border: 0;
    box-shadow: none;
    outline: none;
  }
  [data-slot="input-affix"] {
    display: inline-flex;
    align-items: center;
    height: 20px;
    padding-inline-end: 10px;
    margin-inline-end: 2px;
    color: var(--muted-foreground);
    box-shadow: 1px 0 0 var(--border);
    white-space: nowrap;
  }
  [data-slot="input-affix"]:dir(rtl) {
    box-shadow: -1px 0 0 var(--border);
  }
  [data-slot="input-affix"]:has(> svg:only-child) {
    padding-inline-end: 0;
    box-shadow: none;
  }
  [data-slot="input-trailing"] {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--muted-foreground);
    white-space: nowrap;
    font-size: 12px;
  }
  :is([data-slot="input-affix"], [data-slot="input-trailing"]) svg {
    width: 16px;
    height: 16px;
  }
  [data-slot="docs-toolbar"] [data-slot="input-group"] { max-width: 24rem; }
}

/* not-found-page.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="error-code"] {
    margin: 0;
    font-size: clamp(5rem, 18vw, 8rem);
    font-weight: 700;
    line-height: 1;
    letter-spacing: -0.04em;
    color: color-mix(in srgb, var(--foreground) 12%, transparent);
    font-variant-numeric: tabular-nums;
  }
  [data-slot="suggestion"] {
    display: grid;
    gap: 0.125rem;
    padding: 0.75rem 1rem;
    text-decoration: none;
    color: inherit;
    outline: none;
    transition: background-color var(--duration-fast) var(--ease-out);
  }
  [data-slot="suggestion"]:hover {
    background: var(--muted);
  }
  [data-slot="suggestion"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
  }
}
